{
  "PROP-6a4369e9-pre-009": {
    "property_id": "PROP-6a4369e9-pre-009",
    "audit_result": {
      "property_id": "PROP-6a4369e9-pre-009",
      "classification": "vulnerability",
      "code_path": "beacon_node/network/src/network_beacon_processor/rpc_methods.rs::handle_data_columns_by_root_request_inner::L408-460",
      "proof_trace": "The request validation only limits the number of identifiers to max_request_blocks_deneb (128) at decode time in codec.rs:562-570, but does not validate the total column count. An attacker can send 128 identifiers each with 128 columns for 16384 total columns, exceeding MAX_REQUEST_DATA_COLUMN_SIDECARS. The handler at rpc_methods.rs:408-460 processes all requested columns without checking the sum against spec.max_request_data_column_sidecars.",
      "attack_scenario": "Attacker sends DataColumnsByRoot request with 128 identifiers, each containing max columns per identifier. Total columns requested = 128 * number_of_columns() which can exceed 16384. Node processes all columns, consuming excessive memory and CPU for reconstruction/validation, enabling resource exhaustion DoS.",
      "checklist_id": "PROP-6a4369e9-pre-009"
    },
    "text": "data_column_sidecars_by_root must reject requests exceeding MAX_REQUEST_DATA_COLUMN_SIDECARS.",
    "assertion": "forall req: sum(len(r.columns) for r in req) > MAX_REQUEST_DATA_COLUMN_SIDECARS => rejected(req)",
    "covers": "SG-009",
    "severity": "MEDIUM",
    "type": "pre-condition"
  }
}

