pub fn handle_data_columns_by_root_request(
    self: Arc<Self>,
    peer_id: PeerId,
    inbound_request_id: InboundRequestId,
    request: DataColumnsByRootRequest<T::EthSpec>,
) {
    let requested_columns = request
